  const draw = (c, t) => { const k = Math.cos(Math.PI * EZ.io(sg(t, 0.25, 0.7))); if (Math.abs(k) < 0.01) return; c.translate(CX, CY); c.scale(Math.abs(k), 1); dR(c, 0, 0, 130, 86, 12, k > 0 ? cA : cB); dT(c, k > 0 ? Lx('表', 'FRONT') : Lx('裏', 'BACK'), 0, 2, 28, cK); };
