  const draw = (c, t) => { const q = sg(t, 0.1, 0.95), e = EZ.out(q); for (let k = 0; k < 40; k++) { const a = hash(k) * TAU, d = 40 + 90 * hash(k + 7); dR(c, CX + Math.cos(a) * d * e, CY - 10 + Math.sin(a) * d * e * 0.8 + 90 * q * q, 9, 5 * Math.abs(Math.cos(q * 14 + k)) + 1, 1, [cA, cY, cB, cG, cP][k % 5], 1 - sg(q, 0.75, 1), 400 * q * (hash(k + 3) - 0.5)); } };
