  const draw = (c, t) => { const q = sg(t, 0.3, 0.7), e = EZ.out(q), k = Math.sin(Math.PI * sg(t, 0.3, 0.45)); dL(c, 50, 140, 270, 140, cD, 2); if (q > 0 && q < 1) { c.save(); c.globalAlpha = 1 - q; c.strokeStyle = cY; c.lineWidth = 5 * (1 - q) + 1; c.beginPath(); c.ellipse(CX, 138, 20 + 120 * e, 5 + 26 * e, 0, 0, TAU); c.stroke(); c.restore(); } dE(c, CX, mix(-30, 118, EZ.in(sg(t, 0.1, 0.3))) + 8 * k, 20 * (1 + 0.5 * k), 20 * (1 - 0.4 * k), cA); };
  const cA = "#ff8a5c";
  const cY = "#ffd76a";
  const cD = "#34343e";
  const sg = (t, a, b) => cl((t - a) / (b - a));
  const dE = (c, x, y, rx, ry, col = FG, a = 1) => { if (rx <= 0 || ry <= 0 || a <= 0) return; c.save(); c.globalAlpha *= Math.min(1, a); c.fillStyle = col; c.beginPath(); c.ellipse(x, y, rx, ry, 0, 0, TAU); c.fill(); c.restore(); };
