  const draw = (c, t) => { const s = Math.max(0, EZ.back(sg(t, 0.1, 0.36))); c.translate(104, 136); c.scale(s, s); c.fillStyle = cB; c.beginPath(); c.roundRect(-10, -100, 150, 76, 20); c.moveTo(0, 0); c.lineTo(8, -30); c.lineTo(36, -26); c.closePath(); c.fill(); for (let i = 0; i < 3; i++) dC(c, 40 + i * 25, -62, 7, '#0d1b33', 0.3 + 0.7 * Math.pow(Math.max(0, S(t * 3 - i * 0.15)), 2)); };
